const data = global.get("parat_bridge");

const rayvn_config = msg.payload.rayvn_configured;
const wasos_config = msg.payload.wasos_configured;

if (!rayvn_config || !wasos_config) {
    node.error("Missing configuration — join node did not deliver both systems");
    return null;
}

// Check if this exact pairing already exists
const existing_connection = data.connections.find(c =>
    c.rayvn.log_id === rayvn_config.log_id &&
    c.wasos.chatroom_name === wasos_config.chatroom_name
);

let connection;

if (existing_connection) {
    // Update credentials for existing connection (e.g. after token refresh)
    existing_connection.rayvn = {
        api_key: rayvn_config.api_key,
        log_name: rayvn_config.log_name,
        log_id: rayvn_config.log_id
    };
    existing_connection.wasos = {
        username: wasos_config.username,
        chatroom_name: wasos_config.chatroom_name,
        user_id: wasos_config.user_id || null,
        group: wasos_config.group || null,
        api: {
            key: wasos_config.api_key || (wasos_config.api && wasos_config.api.key),
            expires: wasos_config.expires || (wasos_config.api && wasos_config.api.expires)
        }
    };
    existing_connection.active = true;
    connection = existing_connection;
    node.log("Updated existing connection: " + connection.label);
} else {
    // Create new connection with unique ID

    connection = {
        id: String.hashCode(rayvn_config.log_id + wasos_config.chatroom_name),
        name: rayvn_config.log_name + "_" + wasos_config.chatroom_name,
        time_created: Date.now(),
        label: (rayvn_config.log_name || "Rayvn") + " ↔ " + (wasos_config.chatroom_name || "WaSOS"),
        rayvn: {
            api_key: rayvn_config.api_key,
            log_name: rayvn_config.log_name,
            log_id: rayvn_config.log_id,
            timestamp: Date.now()
        },
        wasos: {
            username: wasos_config.username,
            chatroom_name: wasos_config.chatroom_name,
            user_id: wasos_config.user_id || null,
            group: wasos_config.group || null,
            timestamp: Date.now(),
            api: {
                key: wasos_config.api_key || (wasos_config.api && wasos_config.api.key),
                expires: wasos_config.expires || (wasos_config.api && wasos_config.api.expires)
            }
        },

        active: true,
        master_log: []
    };

    data.connections.push(connection);
    node.log("Created new connection: " + connection.label);
}

global.set("parat_bridge", data);

msg.connection = connection;
msg.payload = connection;
return msg;

